bool kaoruko_decode_frame(size_t frame_index, uint16_t *pixels, size_t pixel_count)
{
    if (frame_index >= KAORUKO_FRAME_COUNT || pixels == NULL || pixel_count != KAORUKO_PIXELS)
        return false;

    size_t input = frame_offsets[frame_index];
    const size_t input_end = frame_offsets[frame_index + 1];
    size_t output = 0;
    while (input < input_end && output < pixel_count)
    {
        const uint8_t flags = compressed_frames[input++];
        for (unsigned bit = 0; bit < 8 && output < pixel_count; ++bit)
        {
            if (flags & (1U << bit))
            {
                if (input_end - input < 2)
                    return false;
                const uint16_t code = (uint16_t)compressed_frames[input] |
                                      ((uint16_t)compressed_frames[input + 1] << 8);
                input += 2;
                const size_t distance = (code >> 4) + 1;
                const size_t length = (code & 0x0f) + 3;
                if (distance > output || length > pixel_count - output)
                    return false;
                for (size_t i = 0; i < length; ++i)
                    pixels[output + i] = pixels[output + i - distance];
                output += length;
            }
            else
            {
                if (input_end - input < 2)
                    return false;
                pixels[output++] = (uint16_t)compressed_frames[input] |
                                   ((uint16_t)compressed_frames[input + 1] << 8);
                input += 2;
            }
        }
    }
    return output == pixel_count && input == input_end;
}
